<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
$checks=0;
function fi_check(bool $ok,string $name): void { global $checks; if (!$ok) throw new RuntimeException($name); $checks++; }
function fi_reject(callable $fn,string $name): void { try { $fn(); } catch (InvalidArgumentException) { fi_check(true,$name); return; } throw new RuntimeException($name); }
$file=sys_get_temp_dir().'/lifeos-fi-'.bin2hex(random_bytes(6)).'.db';
try {
    Db::init($file); $modules=Modules::discover(ROOT.'/app/Modules');
    $dirs=array_merge([ROOT.'/app/Core/migrations'],array_map(fn($m)=>$m['path'].'/migrations',$modules)); Migrator::run($dirs); Migrator::run($dirs);
    fi_check(Db::all('SELECT * FROM intelligence_sources')===[],'Fresh profiles contain no notes or generated history');
    $task=PlannerService::saveTask(null,['title'=>'Write report','due'=>'2026-10-01']);
    $habit=PlannerService::saveHabit(null,['title'=>'Study']); $now=time();
    $session=FocusService::start('Report',25,'study',$now,['task_id'=>$task,'habit_id'=>$habit,'minimum_minutes'=>25]);
    FocusService::action($session,'finish',$now+1500); FocusService::action($session,'finish',$now+3000);
    fi_check(count(Db::all('SELECT * FROM focus_task_logs'))===1 && Db::one('SELECT seconds FROM focus_task_logs')['seconds']===1500,'Completed session logs bounded actual seconds exactly once');
    fi_check(count(Db::all('SELECT * FROM focus_habit_events'))===1 && count(Db::all('SELECT * FROM planner_habit_checks'))===1,'Focus completion creates one traceable habit check');
    $early=FocusService::start('Early',25,'study',$now,['task_id'=>$task,'habit_id'=>$habit]); FocusService::action($early,'finish',$now+60);
    fi_check(count(Db::all('SELECT * FROM focus_task_logs'))===2 && count(Db::all('SELECT * FROM focus_habit_events'))===1,'Early completion records time without satisfying habit threshold');
    $pause=FocusService::start('Pause',25,'study',$now,['task_id'=>$task]); FocusService::action($pause,'pause',$now+120); FocusService::action($pause,'resume',$now+600); FocusService::action($pause,'finish',$now+660);
    fi_check(Db::one('SELECT seconds FROM focus_task_logs WHERE session_id=?',[$pause])['seconds']===180,'Paused time is excluded');
    $break=FocusService::start('Rest',25,'break',$now,['task_id'=>$task,'habit_id'=>$habit]); FocusService::action($break,'finish',$now+1500);
    $cancel=FocusService::start('Cancelled',25,'study',$now,['task_id'=>$task]); FocusService::action($cancel,'cancel',$now+1500);
    fi_check(!Db::one('SELECT 1 FROM focus_task_logs WHERE session_id IN (?,?)',[$break,$cancel]),'Break and cancelled sessions do not log task time');
    $again=FocusService::start('Again',25,'study',$now,['habit_id'=>$habit]); FocusService::action($again,'finish',$now+1500);
    fi_check(count(Db::all('SELECT * FROM planner_habit_checks'))===1 && count(Db::all('SELECT * FROM focus_habit_events'))===2,'Second eligible session does not toggle existing habit off');
    fi_reject(fn()=>FocusService::start('Invalid link',25,'study',$now,['task_id'=>999999]),'Nonexistent task link rejected');
    fi_reject(fn()=>FocusService::start('Invalid habit',25,'study',$now,['habit_id'=>999999]),'Nonexistent habit link rejected');
    fi_reject(fn()=>FocusService::start('Invalid threshold',25,'study',$now,['minimum_minutes'=>0]),'Zero habit threshold rejected');
    $items=IntelligenceService::extract("Meeting context only.\nAction: Send the report\n- [ ] Review account\nCall Amma tomorrow\nAction: Send the report");
    fi_check(count($items)===3 && $items[0]['title']==='Send the report','Notes extract explicit action lines and deduplicate');
    fi_check(IntelligenceService::extract('We discussed many possibilities.')===[],'Ordinary prose is not silently converted to tasks');
    $source=IntelligenceService::source('note',"Action: Send the report\n- Review account"); $draft=IntelligenceService::draftTasks($source);
    fi_check(count(Db::all('SELECT * FROM tasks'))===1,'Generating a preview creates no tasks');
    IntelligenceService::apply($draft,['items'=>[['title'=>'Send final report','due'=>'2026-11-05'],['title'=>'Review account','skip'=>'on']]]);
    fi_check(count(Db::all('SELECT * FROM tasks'))===2 && count(Db::all('SELECT * FROM intelligence_task_links'))===1,'Review edits and exclusions create linked tasks');
    fi_reject(fn()=>IntelligenceService::apply($draft),'Applied preview cannot create duplicate tasks');
    fi_check(IntelligenceService::sourceRow($source)['body']==="Action: Send the report\n- Review account",'Original note is retained');
    $move=IntelligenceService::movePreview('move all overdue tasks to tomorrow','2026-11-03');
    fi_check(PlannerService::task($task)['due']==='2026-10-01','Move preview changes no dates');
    IntelligenceService::apply($move); fi_check(PlannerService::task($task)['due']==='2026-11-04','Confirmed move sets tomorrow');
    IntelligenceService::undo($move); fi_check(PlannerService::task($task)['due']==='2026-10-01','Undo restores original due date');
    fi_reject(fn()=>IntelligenceService::undo($move),'Undo cannot run twice');
    $stale=IntelligenceService::movePreview('move task #'.$task.' to tomorrow','2026-11-03'); Db::run('UPDATE tasks SET due=? WHERE id=?',['2026-10-02',$task]);
    fi_reject(fn()=>IntelligenceService::apply($stale),'Preview rejects a task changed since preview');
    fi_reject(fn()=>IntelligenceService::movePreview('delete all tasks'),'Destructive commands are not supported');
    Db::run('UPDATE tasks SET deadline=? WHERE id=?',['2026-11-04',$task]);
    fi_reject(fn()=>IntelligenceService::movePreview('move task #'.$task.' to 2026-11-05'),'Natural-language move respects hard task deadline');
    Db::run('UPDATE tasks SET deadline=NULL WHERE id=?',[$task]);
    Db::run('INSERT INTO planner_blocks(task_id,starts_at,ends_at,pinned) VALUES (?,?,?,1)',[$task,'2026-11-06 09:00','2026-11-06 09:30']);
    fi_reject(fn()=>IntelligenceService::movePreview('move task #'.$task.' to 2026-11-05'),'Due-only move cannot precede an existing pinned block');
    $blockSensitive=IntelligenceService::movePreview('move task #'.$task.' to 2026-11-07');
    Db::run('UPDATE planner_blocks SET pinned=0 WHERE task_id=?',[$task]);
    fi_reject(fn()=>IntelligenceService::apply($blockSensitive),'Changed schedule invalidates due-date action preview');
    Db::run('DELETE FROM planner_blocks WHERE task_id=?',[$task]);
    fi_reject(fn()=>IntelligenceService::movePreview('move task #999999 to tomorrow'),'Missing task command rejected');
    fi_reject(fn()=>IntelligenceService::ask('Spending?'),'Ollama adapter requires opt-in');
    IntelligenceService::configure(['enabled'=>'on','model'=>'gemma3:4b']);
    $answer=IntelligenceService::ask('How much?',static function (array $payload): array { fi_check($payload['stream']===false && count($payload['messages'])===2,'Ollama uses bounded non-streaming chat'); return ['message'=>['content'=>'Use the recorded facts.']]; });
    fi_check($answer['facts']['open_tasks']===2 && $answer['answer']==='Use the recorded facts.','Facts are calculated separately from model wording');
    fi_reject(fn()=>IntelligenceService::configure(['model'=>'../bad model;command']),'Invalid model token rejected');
    fi_reject(fn()=>IntelligenceService::configure(['tesseract'=>'missing-program.exe']),'Nonexistent executable rejected');
    $receipt=IntelligenceService::source('receipt',"Test Store\n2026-11-03\nSubtotal 900.00\nGrand Total LKR 1,025.50"); $rd=IntelligenceService::receiptDraft($receipt); $payload=json_decode(IntelligenceService::draft($rd)['payload'],true);
    fi_check($payload['amount']==='1025.50' && $payload['date']==='2026-11-03','Receipt selects labelled total and recognized date');
    $account=(int)Db::one('SELECT id FROM accounts ORDER BY id LIMIT 1')['id']; $category=(int)Db::one('SELECT id FROM expense_categories ORDER BY id LIMIT 1')['id'];
    $balance=(float)Db::one('SELECT balance FROM accounts WHERE id=?',[$account])['balance'];
    fi_check(Db::all('SELECT * FROM expenses')===[],'Receipt OCR preview creates no expense');
    IntelligenceService::apply($rd,['amount'=>'1025.50','date'=>'2026-11-03','account_id'=>$account,'category_id'=>$category,'note'=>'Confirmed merchant']);
    fi_check((float)Db::one('SELECT balance FROM accounts WHERE id=?',[$account])['balance']===$balance-1025.50 && count(Db::all('SELECT * FROM expenses'))===1,'Reviewed receipt uses financial debit service');
    fi_reject(fn()=>IntelligenceService::apply($rd,[]),'Receipt draft cannot post twice');
    $repeatedReceipt=IntelligenceService::receiptDraft($receipt);
    fi_reject(fn()=>IntelligenceService::apply($repeatedReceipt,['amount'=>'1025.50','date'=>'2026-11-03','account_id'=>$account,'category_id'=>$category,'note'=>'Duplicate']),'Re-previewing one receipt source cannot debit twice');
    // Force status to change after the outer preview read but before its claim.
    $racedSource=IntelligenceService::source('receipt',"Race fixture\nTotal LKR 20.00"); $racedDraft=IntelligenceService::receiptDraft($racedSource);
    $balanceBeforeRace=(float)Db::one('SELECT balance FROM accounts WHERE id=?',[$account])['balance'];
    $expensesBeforeRace=count(Db::all('SELECT * FROM expenses'));
    Db::exec("CREATE TRIGGER intelligence_receipt_stale_status BEFORE INSERT ON expenses WHEN NEW.note='Race fixture' BEGIN UPDATE intelligence_drafts SET status='applied' WHERE id=".$racedDraft."; END");
    fi_reject(fn()=>IntelligenceService::apply($racedDraft,['amount'=>'20.00','date'=>'2026-11-03','account_id'=>$account,'category_id'=>$category,'note'=>'Race fixture']),'Receipt rejects status changed between preview read and transactional claim');
    fi_check((float)Db::one('SELECT balance FROM accounts WHERE id=?',[$account])['balance']===$balanceBeforeRace && count(Db::all('SELECT * FROM expenses'))===$expensesBeforeRace && IntelligenceService::draft($racedDraft)['status']==='preview','Lost receipt claim rolls back debit, expense and transactional changes');
    Db::exec('DROP TRIGGER intelligence_receipt_stale_status');
    $rollbackSource=IntelligenceService::source('note','Action: Must remain atomic'); $rollbackDraft=IntelligenceService::draftTasks($rollbackSource);
    $taskCountBeforeFailure=count(Db::all('SELECT * FROM tasks'));
    Db::exec("CREATE TRIGGER intelligence_task_apply_failure BEFORE INSERT ON tasks WHEN NEW.title='Must remain atomic' BEGIN SELECT RAISE(ABORT,'Deliberate claim rollback test'); END");
    try { IntelligenceService::apply($rollbackDraft); throw new RuntimeException('Expected task insertion failure'); } catch (PDOException $expected) {}
    fi_check(IntelligenceService::draft($rollbackDraft)['status']==='preview' && count(Db::all('SELECT * FROM tasks'))===$taskCountBeforeFailure,'Failed task creation rolls back its early transactional claim');
    Db::exec('DROP TRIGGER intelligence_task_apply_failure');
    fi_reject(fn()=>LocalMediaService::convert('missing','receipt'),'OCR needs configured executable');
    fi_check(WeatherService::brief()===null,'Weather makes no request without opt-in');
    fi_reject(fn()=>WeatherService::configure(true,'91','80'),'Weather rejects invalid coordinates');
    fi_check(str_contains(WeatherService::parse(['current'=>['temperature_2m'=>28.5,'precipitation'=>0.2,'time'=>'2026-11-03T07:00']]),'28.5 °C'),'Weather response includes temperature and timestamp');
    fi_reject(fn()=>WeatherService::parse(['current'=>[]]),'Malformed weather data rejected');
    fi_check(LocalMediaService::command([PHP_BINARY,'-r','echo $argv[1];','literal & $(no-shell) `value`'])==='literal & $(no-shell) `value`','Local commands pass literal arguments without shell evaluation');
    fi_reject(fn()=>LocalMediaService::command([PHP_BINARY,'-r','exit(5);']),'Local command failure is surfaced');
    fi_check(Db::all('PRAGMA foreign_key_check')===[],'All generated links preserve foreign keys');
    echo $checks." focus/intelligence checks passed.\n";
} finally { Db::close(); foreach ([$file,$file.'-shm',$file.'-wal'] as $f) if (is_file($f)) unlink($f); }
